import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateMeet } from "../handlers/updateMeet";
import type { ApiError } from "../runtime/client";
import type { SpaceMeetEntityType } from "../types/SpaceMeetEntityType";
import type { SpacePartition } from "../types/SpacePartition";
import type { UpdateMeetRequest } from "../types/UpdateMeetRequest";

type Data = Awaited<ReturnType<typeof updateMeet>>;
type Vars = { spacePk: SpacePartition; meetSk: SpaceMeetEntityType; req: UpdateMeetRequest };

export function useUpdateMeet(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateMeet(vars.spacePk, vars.meetSk, vars.req),
    ...options,
  });
}
